from .modeller import Odunc

# Üye türüne göre aynı anda ödünçte tutulabilecek kitap sınırı
ODUNC_SINIRLARI = {"standart": 3, "ogrenci": 5}


def ceza_hesapla(alinma: date, iade: date, tur: str) -> float:
    """Gecikme cezasını hesaplar.

    Ödünç süresi 14 gündür (gün sayısı = iade - alınma). Aşan her gün gecikmedir;
    ilk 7 gün için günlük 2,50 TL, sonraki günler için günlük 5,00 TL uygulanır ve
    ceza en fazla 150 TL olabilir. Üye türü "ogrenci" ise sınırdan sonra %50 indirimlidir.
    """
    gun = (iade - alinma).days
    gecikme = max(0, gun - 14)
    if gecikme <= 0:
        ceza = 0.0
    else:
        ilk_7 = min(gecikme, 7) * 2.50
        kalan = max(0, gecikme - 7) * 5.00
        ceza = min(150.0, ilk_7 + kalan)
    if tur == "ogrenci":
        ceza *= 0.50
    return round(ceza, 2)


class KutuphaneServisi:
    def __init__(self):
        self.kitaplar = {}
        self.uyeler = {}
        self.kayitlar = []

    def kitap_ekle(self, kitap):
        self.kitaplar[kitap.id] = kitap

    def uye_ekle(self, uye):
        self.uyeler[uye.id] = uye

    def _aktif(self, kitap_id):
        return next((k for k in self.kayitlar if k.kitap_id == kitap_id and k.iade is None), None)

    def odunc_ver(self, kitap_id, uye_id, tarih):
        """Kitabı üyeye verir. Kitap/üye yoksa ya da kitap zaten ödünçteyse ValueError."""
        if kitap_id not in self.kitaplar or uye_id not in self.uyeler:
            raise ValueError("kitap ya da üye bulunamadı")
        if self._aktif(kitap_id):
            raise ValueError("kitap zaten ödünçte")
        uye = self.uyeler[uye_id]
        sinir = ODUNC_SINIRLARI.get(uye.tur, 3)
        if len(self.oduncteki_kitaplar(uye_id)) >= sinir:
            raise ValueError(f"ödünç limiti aşıldı ({sinir})")
        kayit = Odunc(kitap_id, uye_id, tarih)
        self.kayitlar.append(kayit)
        return kayit

    def iade_al(self, kitap_id, tarih):
        """Kitabın iadesini alır, gecikme cezasını hesaplayıp kayda yazar ve kaydı döndürür.

        Kitap ödünçte değilse ValueError."""
        kayit = self._aktif(kitap_id)
        if kayit is None:
            raise ValueError("kitap ödünçte değil")
        uye = self.uyeler[kayit.uye_id]
        kayit.iade = tarih
        kayit.ceza = ceza_hesapla(kayit.alinma, tarih, uye.tur)
        return kayit

    def oduncteki_kitaplar(self, uye_id):
        return sorted(k.kitap_id for k in self.kayitlar if k.uye_id == uye_id and k.iade is None)

    def toplam_ceza(self, uye_id):
        """Üyenin iade edilmiş tüm ödünçlerinin cezaları toplamı."""
        return round(sum(k.ceza for k in self.kayitlar if k.uye_id == uye_id), 2)

